import{_ as t,o as r,c as o,ae as a}from"./chunks/framework.BX6FPmO9.js";const u=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/system-overview.md","filePath":"architecture/system-overview.md"}'),i={name:"architecture/system-overview.md"};function s(l,e,c,d,n,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：1</p><p>這份文件聚焦於「大型協作」所需的結構與流程。</p><p>專案朝向 <strong>兩個方向</strong> 對齊：</p><ol><li><p><strong>乾淨架構（業務規格做專案中樞）</strong><br> 以 <strong>docs/product/</strong> 為業務規格中樞；功能與資料流可追溯到規格，依賴由外而內。<br> 見 <a href="./clean-architecture.html">clean-architecture</a>。</p></li><li><p><strong>半自動化 UI / Design System</strong><br> 逐漸建立 design system（tokens、core 元件、使用規範），以單一來源與半自動化維持 UI 一致性。<br> 見 <a href="./design-system.html">design-system</a>、<a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a>。</p></li></ol><h3 id="五層分層-repo-架構" tabindex="-1">五層分層（Repo 架構） <a class="header-anchor" href="#五層分層-repo-架構" aria-label="Permalink to &quot;五層分層（Repo 架構）&quot;">​</a></h3><p>程式碼依 <strong>app / features / components / services / infra</strong> 五層分層，方便區分「產品功能」與「平台能力」；依賴方向與禁止規則見 <a href="./repo-layers.html">repo-layers</a>。</p><table tabindex="0"><thead><tr><th>層級</th><th>責任</th><th>本專案目錄</th></tr></thead><tbody><tr><td><strong>app</strong></td><td>application shell（routing、layout、bootstrap）</td><td><code>app/routes</code>、<code>app/root.tsx</code>、<code>app/entry.*</code></td></tr><tr><td><strong>features</strong></td><td>product features（domain boundary）</td><td><code>app/features/*</code></td></tr><tr><td><strong>components</strong></td><td>reusable UI（ui / shared / app 子層）</td><td><code>app/components/*</code></td></tr><tr><td><strong>services</strong></td><td>API / domain access</td><td><code>app/services/*</code>、<code>app/shared/*</code></td></tr><tr><td><strong>infra</strong></td><td>技術基礎設施（可選）</td><td><code>app/infra/*</code>（視需求擴充）</td></tr></tbody></table><h2 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;">​</a></h2><ul><li>Remix v2 + React 18</li><li>TypeScript</li><li>Vite</li><li>Tailwind CSS</li><li>Node.js &gt;= 20</li></ul><p>套件與 React 支援度對照見 <a href="./../conventions/packages-react.html">packages-react</a>；新增或升級依賴時請維護該表並確認 React 相容性。</p><h2 id="directory-structure" tabindex="-1">Directory Structure <a class="header-anchor" href="#directory-structure" aria-label="Permalink to &quot;Directory Structure&quot;">​</a></h2><p>對應五層分層（詳見 <a href="./repo-layers.html">repo-layers</a>）：</p><ul><li><strong>App shell</strong>：<code>app/routes/*</code>、<code>app/root.tsx</code>、<code>app/entry.*</code></li><li><strong>Features</strong>：<code>app/features/*</code><ul><li><code>*.hooks.ts</code>: 前端 hook</li><li><code>*.server.ts</code>: server-side 資料處理</li><li><code>*.types.ts</code>: 模組型別定義</li></ul></li><li><strong>Components</strong>：<code>app/components/*</code>（ui / shared / app 子層）</li><li><strong>Services</strong>：<code>app/services/*</code>（應用層整合）、<code>app/shared/*</code>（contracts、api、types、utils、services）</li><li><strong>Infra</strong>（可選）：<code>app/infra/*</code> — 環境設定、logger、analytics 等，視需求擴充</li></ul><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><ul><li>UI 呼叫 <code>app/features/*/*.hooks.ts</code></li><li>hooks 透過 Remix route / loader / action 互動</li><li>server-side logic 位於 <code>app/features/*/*.server.ts</code></li><li>跨模組協作由 <code>app/shared/services</code> 串接</li><li>LUI 串流由 <code>app/routes/api.chat.ts</code> (SSE Resource Route) 提供</li></ul><h2 id="quality-gates" tabindex="-1">Quality Gates <a class="header-anchor" href="#quality-gates" aria-label="Permalink to &quot;Quality Gates&quot;">​</a></h2><ul><li>ESLint: 嚴格型別檢查 + import sorting + unused imports</li><li>Prettier: 統一格式</li><li>TypeScript: typecheck</li><li>Knip: unused code 掃描</li><li>Husky + lint-staged: 預提交自動修正</li></ul><h2 id="ci-cd" tabindex="-1">CI/CD <a class="header-anchor" href="#ci-cd" aria-label="Permalink to &quot;CI/CD&quot;">​</a></h2><ul><li>GitHub Actions <ul><li>PR: lint:strict + typecheck + knip</li><li>Deploy: main 分支自動部署</li></ul></li></ul><h2 id="collaboration-conventions" tabindex="-1">Collaboration Conventions <a class="header-anchor" href="#collaboration-conventions" aria-label="Permalink to &quot;Collaboration Conventions&quot;">​</a></h2><ul><li>PR 必附測試或說明</li><li>以小步、可回滾的改動為主</li><li>建議使用 Conventional Commits 以便未來版本管理</li></ul>',22)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
